        "const STATES={\n  surplus:{\n    cls:'surplus',label:'My cup is full',phrase:'My cup is full',\n    sub:'You are above your ceiling — surplus is flowing outward through your trust channels toward those in need.',\n    posLabel:'$17,400 / $15,000 ceiling',bandPos:'95%',dotColor:'var(--green)',\n    netLabel:'+$5,200 net outflow',netCls:'net-pos',\n    summaryIn:'+$2,100',summaryOut:'−$7,300',summaryNet:'+$2,100 in · flowing out'\n  },\n  balanced:{\n    cls:'balanced',label:'Gradient band',phrase:'In the flow',\n    sub:'You are between floor and ceiling — flowing some surplus out while remaining positioned to receive support if needed.',\n    posLabel:'$11,200 / $15,000 ceiling',bandPos:'74%',dotColor:'var(--accent)',\n    netLabel:'+$2,100',netCls:'net-pos',\n    summaryIn:'+$3,840',summaryOut:'−$1,855',summaryNet:'+$1,985'\n  },\n  deficit:{\n    cls:'deficit',label:'In deficit',phrase:'In deficit',\n    sub:'You are below floor. Support is drawing in from your network. No action needed — the protocol is working.',\n    posLabel:'$5,800 / $7,000 floor',bandPos:'35%',dotColor:'var(--yellow)',\n    netLabel:'−$1,200 drawing in',netCls:'net-neg',\n    summaryIn:'+$1,200',summaryOut:'−$0 (outflow paused)',summaryNet:'−$1,200 drawing support'\n  },\n  firstrun:{cls:'balanced',label:'',phrase:'',sub:'',posLabel:'',bandPos:'50%',dotColor:'var(--text2)',netLabel:'',netCls:''}\n};\n\nfunction setState(s){\n  const st=STATES[s]||STATES.balanced;\n  const hero=document.getElementById('stateHero');\n  hero.className='state-hero '+st.cls;\n  document.getElementById('stateLabel').textContent=st.label;\n  document.getElementById('statePhrase').textContent=st.phrase;\n  document.getElementById('stateSub').textContent=st.sub;\n  document.getElementById('posLabel').textContent=st.posLabel;\n  document.getElementById('currentDot').style.left=st.bandPos;\n  document.getElementById('currentDot').style.background=st.dotColor;\n  document.getElementById('netLabel').textContent=st.netLabel;\n  document.getElementById('netLabel').style.color=st.netCls==='net-neg'?'var(--yellow)':'var(--green)';\n  document.getElementById('summaryIn').textContent=st.summaryIn||'+$3,840';\n  document.getElementById('summaryOut').textContent=st.summaryOut||'−$1,855';\n  document.getElementById('summaryNet').textContent=st.summaryNet||'+$1,985';\n  const fr=document.getElementById('firstRun');\n  const rc=document.getElementById('riverContent');\n  // First run (no flows): hide the state hero (the \"cup full\" band + Simulate),\n  // the period nav, and the tab strip — show only the empty-state prompt. None\n  // of that chrome means anything before the first flow exists.\n  const stateChrome=[hero,document.getElementById('periodNav'),document.getElementById('tabStrip')];\n  if(s==='firstrun'){\n    fr.classList.remove('hidden');rc.classList.add('hidden');\n    stateChrome.forEach(e=>e&&e.classList.add('hidden'));\n  } else {\n    fr.classList.add('hidden');rc.classList.remove('hidden');\n    stateChrome.forEach(e=>e&&e.classList.remove('hidden'));\n  }\n}\nfunction switchTab(el,id){\n  document.querySelectorAll('.tabstrip button').forEach(b=>b.classList.remove('on'));\n  el.classList.add('on');\n}",
